SELECT COUNT(*) AS stays_over_seven_days
FROM syn_stays
WHERE EXTRACT(INTERVAL '1 DAY' FROM (syn_stays.STOP - syn_stays.START)) > 7;

SELECT COUNT(*) AS nonmissing_reason_count
FROM syn_stays
WHERE reason IS NOT NULL;

SELECT COUNT(*) 
FROM syn_risk_scores 
WHERE risk_lr >= 0.2;

SELECT GENDER, AVG(los_days) AS avg_los
FROM syn_stays
GROUP BY GENDER;

SELECT GENDER, MAX(los_days) AS max_los_days
FROM syn_stays
GROUP BY GENDER;

SELECT GENDER, AVG(lace) AS avg_lace_score
FROM syn_risk_scores
GROUP BY GENDER;

SELECT COUNT(DISTINCT s.PATIENT)
FROM syn_stays s
INNER JOIN syn_risk_scores r ON s.PATIENT = r.PATIENT AND s.START = r.START AND s.STOP = r.STOP;
